      }
    }
  } else if (beforeId) {
    newPos = (beforePos ?? 0) + 1000;
  } else if (afterId) {
    newPos = (afterPos ?? 0) - 1000;
    if (newPos < 0) newPos = 0;
  } else {
    // empty column or append
