{"path": "backend/server.js", "content": "const express = require('express');
const cors = require('cors');
const path = require('path');
const fs = require('fs');
const { PGlite } = require('@electric-sql/pglite');

const app = express();
app.use(cors());
app.use(express.json());

const DATA_DIR = path.join(__dirname, 'data');
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

// Initialize PGlite
const db = new PGlite(DATA_DIR);

async function initDb() {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id SERIAL PRIMARY KEY,
      title TEXT NOT NULL,
      position NUMERIC NOT NULL
    );
    CREATE TABLE IF NOT EXISTS cards (
      id SERIAL PRIMARY KEY,
      column_id INTEGER REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT NOT NULL,
      position NUMERIC NOT NULL,
      created_at TIMESTAMP DEFAULT now()
    );
  `);

  // Seed default columns if empty
  const { rows: cols } = await db.query('SELECT id FROM columns');
  if (cols.length === 0) {
    await db.exec(`
      INSERT INTO columns (title, position) VALUES
      ('To Do', 1000),
      ('In Progress', 2000),
      ('Done', 3000);
    `);
  }
}

initDb().catch(err => {
  console.error('DB init error', err);
  process.exit(1);
});

// SSE clients
const clients = new Set();

function broadcast(eventType, data) {
  const payload = `event: ${eventType}\n data: ${JSON.stringify(data)}\n\n`;
  for (const res of clients) {
    try {
      res.write(payload);
    } catch (e) {
      clients.delete(res);
    }
  }
}

// API: Get board
app.get('/api/board', async (req, res) => {
  try {
    const { rows: columns } = await db.query('SELECT id, title, position FROM columns ORDER BY position');
