    // Check if renormalization needed
    const { rows: neighbors } = await db.query(
      'SELECT position FROM cards WHERE column_id = $1 AND id != $2 ORDER BY position',
      [columnId, cardId]
    );
    // Simple check: if newPos is very close to neighbors, renormalize
